-- 한글 표현 개편 (2026-09-26). 기준: notes/style/korean-voice.md
-- 이미 누가 번역을 제출한 한→영 원문은 바꾸지 않는다(where not exists drill_answers).
begin;
update public.drills set source='첫 달은 저희가 낼게요. 해지는 버튼 하나로.' where id='dr-20260926-ke-m1' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-m1');
update public.drill_models set best='Your first month is on us. Canceling takes one tap.', alternatives='["First month''s on us, and canceling is just one click.", "Try it free for a month. Leave anytime, no hoops."]', notes='[{"phrase": "저희가 낼게요 → on us", "why": "''무료'' 대신 ''저희가 낸다''로 호의를 보여 주는 카피예요. 영어의 on us가 딱 같은 뉘앙스예요."}, {"phrase": "해지는 버튼 하나로 → Canceling takes one tap", "why": "한국어 카피는 명사로 끝내 여운을 두지만, 영어는 동사를 살린 짧은 문장이 자연스러워요. 모바일이면 tap, 웹이면 click."}]' where drill_id='dr-20260926-ke-m1' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-m1');
update public.drills set source='오븐 문이 열렸어요. 오늘의 빵은 무화과 캄파뉴.' where id='dr-20260926-ke-m2' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-m2');
update public.drill_models set best='Fresh out of the oven: today it''s fig campagne.', alternatives='["The oven''s open. Today''s loaf: fig campagne.", "Just baked this morning: fig campagne."]', notes='[{"phrase": "오븐 문이 열렸어요 → Fresh out of the oven", "why": "갓 구웠다는 사실을 장면으로 보여 주는 카피예요. 영어에는 fresh out of the oven이라는 굳어진 표현이 있어요."}, {"phrase": "오늘의 빵은 ~ → today it''s ~ / Today''s loaf:", "why": "명사로 끝나는 한국어 카피는 영어에서 콜론(:)이나 it''s로 받으면 리듬이 살아요."}]' where drill_id='dr-20260926-ke-m2' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-m2');
update public.drills set source='딱 300개만 만들었어요. 다시 만들 계획은 없어요.' where id='dr-20260926-ke-m3' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-m3');
update public.drill_models set best='We made just 300. And we''re not making more.', alternatives='["Only 300 made. Once they''re gone, they''re gone.", "A run of 300, and no restocks."]', notes='[{"phrase": "딱 300개만 → just 300", "why": "''한정 수량''보다 숫자를 밝히는 게 요즘 카피의 설득 방식이에요. 영어도 just, only로 짧게 써요."}, {"phrase": "다시 만들 계획은 없어요 → we''re not making more / no restocks", "why": "''서두르세요'' 같은 재촉 대신 사실만 말해 희소성을 전해요. Once they''re gone, they''re gone은 굳어진 표현이에요."}]' where drill_id='dr-20260926-ke-m3' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-m3');
update public.drills set source='제안 주신 대로 목요일 오후 2시로 회의를 확정하겠습니다.' where id='dr-20260926-ke-b1' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-b1');
update public.drill_models set notes='[{"phrase": "제안 주신 대로 → as you suggested", "why": "상대 제안을 받아들이는 업무 메일에서는 as you suggested가 자연스러워요. as you said보다 정중해요."}, {"phrase": "확정하겠습니다 → I''d like to confirm", "why": "decide가 아니라 confirm이에요. I''d like to로 공손함을 살려요."}]' where drill_id='dr-20260926-ke-b1' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-b1');
update public.drills set source='앞선 메일에 파일이 빠져 다시 보내 드립니다.' where id='dr-20260926-ke-b2' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-b2');
update public.drill_models set notes='[{"phrase": "파일이 빠져 → I forgot to attach / the attachment was missing", "why": "한국어는 ''파일이 빠졌다''처럼 사물을 주어로 부드럽게 사과해요. 영어는 I forgot to attach로 내 실수를 짧게 인정하는 편이 깔끔해요."}, {"phrase": "다시 보내 드립니다 → Please find it attached", "why": "업무 메일에서 첨부를 알리는 굳어진 표현이에요. 조금 편하게는 Here it is."}]' where drill_id='dr-20260926-ke-b2' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-b2');
update public.drills set source='번거로우시겠지만 자료 제출을 금요일까지 미뤄 주실 수 있을까요?' where id='dr-20260926-ke-b3' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-b3');
update public.drill_models set notes='[{"phrase": "번거로우시겠지만 → (생략) / I''m sorry to ask, but", "why": "부탁 앞의 쿠션어는 영어에서 자주 빼고, Would it be possible로 공손함을 대신해요."}, {"phrase": "금요일까지 미뤄 주실 수 있을까요 → extend the deadline to Friday", "why": "기한을 늦추는 건 extend the deadline이나 push the deadline back이에요. delay the deadline은 어색해요."}]' where drill_id='dr-20260926-ke-b3' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-b3');
update public.drills set source='여기 완전 내 취향이야. 다음에 또 오자.' where id='dr-20260926-ke-d3' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-d3');
update public.drill_models set notes='[{"phrase": "내 취향이야 → my vibe / right up my alley", "why": "This is my taste보다 구어에서는 my vibe나 right up my alley가 자연스러워요."}, {"phrase": "다음에 또 오자 → Let''s come back sometime", "why": "next time을 꼭 넣지 않아도 돼요. come back, come again이 다시 온다는 뜻이에요."}]' where drill_id='dr-20260926-ke-d3' and not exists (select 1 from public.drill_answers a where a.drill_id='dr-20260926-ke-d3');
update public.drill_models set best='소음은 끄고, 나를 켜세요.', alternatives='["세상은 조용히, 나는 선명하게.", "소리는 줄이고, 나에게 집중."]', notes='[{"phrase": "Less noise. More you.", "why": "''더 많은 당신''처럼 직역하면 어색해요. 끄다/켜다 같은 반대말 짝으로 대구를 살리면 노이즈 캔슬링이라는 기능까지 떠올라요."}, {"phrase": "you", "why": "영어 카피의 you는 한국어에서 빼거나 ''나''로 바꾸면 자연스러워요. 광고의 ''당신''은 거리감이 느껴질 수 있어요."}]' where drill_id='dr-ek-m1';
update public.drill_models set best='주말 동안만, 50달러부터 무료 배송', alternatives='["이번 주말엔 50달러만 넘어도 배송비 0원", "배송비는 저희가. 50달러 이상, 주말까지만."]', notes='[{"phrase": "this weekend only", "why": "''한정!''처럼 느낌표로 재촉하기보다 ''주말 동안만''처럼 담백하게 기한을 알리는 게 요즘 톤이에요."}, {"phrase": "orders over $50", "why": "over는 엄밀히 ''50달러 초과''예요. 한국 쇼핑몰은 보통 ''~부터'', ''~ 이상''이라고 써요. 약관처럼 정확해야 하면 ''초과''를 써요."}]' where drill_id='dr-ek-m2';
update public.drill_models set best='바르는 순간 스며드는, 끈적임 없는 가벼움', alternatives='["가볍게 스며들고, 산뜻하게 마무리돼요.", "닿자마자 사라지듯 스며드는 텍스처"]', notes='[{"phrase": "formula", "why": "화장품에서는 ''제형''이나 ''텍스처''라고 해요. 요즘 카피는 제형을 명사로 내세우기보다 ''가벼움'', ''산뜻함'' 같은 사용감으로 보여 줘요."}, {"phrase": "non-greasy", "why": "''기름지지 않은''보다 ''끈적임 없는'', ''산뜻한''이 화장품 문구에 맞는 말이에요."}, {"phrase": "in seconds", "why": "''몇 초 만에''로 직역하기보다 ''바르는 순간'', ''닿자마자''처럼 장면으로 옮기면 카피답게 들려요."}]' where drill_id='dr-ek-m3';
update public.drill_models set best='새로 들어온 것, 나만 받는 혜택. 가장 먼저 알려 드릴게요.', alternatives='["신상과 멤버 전용 혜택, 제일 먼저 받아 보세요.", "입고 소식과 단독 혜택을 누구보다 빨리."]' where drill_id='dr-ek-m4';
update public.drill_models set best='시작은 하나의 질문이었어요. 좋은 디자인은 왜 늘 비쌀까?', alternatives='["좋은 디자인이 꼭 비쌀 필요가 있을까. 우리는 여기서 출발했습니다.", "좋은 디자인을, 부담 없는 가격에. 그 질문에서 시작했어요."]', notes='[{"phrase": "why can''t good design be affordable?", "why": "부정 의문문을 그대로 옮기면(왜 저렴할 수 없을까) 어색해요. ''왜 늘 비쌀까''처럼 뒤집으면 뜻은 같고 더 자연스러워요."}, {"phrase": "affordable", "why": "''저렴한''은 싸구려 느낌이 날 수 있어요. 브랜드 문장에서는 ''부담 없는 가격'', ''합리적인 가격''을 써요."}]' where drill_id='dr-ek-m5';
update public.drill_models set best='식단은 미리, 시간은 넉넉히, 버리는 음식은 조금만.', alternatives='["미리 짜는 식단 하나로 시간도, 음식도 아껴요.", "장보기부터 남는 음식까지, 한 번에 가볍게."]', notes='[{"phrase": "Plan, save, waste less", "why": "영어의 명령문 세 개는 한국어에서 ''~은 ~하게''를 세 번 반복하는 대구로 옮기면 리듬이 살아요."}, {"phrase": "waste less food", "why": "''음식을 덜 낭비하다''보다 ''버리는 음식'', ''음식물 쓰레기''가 한국어에서 자연스럽게 쓰는 말이에요."}]' where drill_id='dr-ek-m6';
update public.drill_models set best='멀리 달리게, 오래 신게.', alternatives='["긴 거리에도, 긴 세월에도.", "멀리 가는 사람을 위해."]', notes='[{"phrase": "the long run", "why": "장거리 달리기와 in the long run(오래도록)을 겹친 말장난이에요. ''멀리 달리게, 오래 신게''처럼 대구로 두 뜻을 다 살려요."}, {"phrase": "Built for", "why": "''~를 위해 만들어진''은 번역투가 되기 쉬워요. 카피에서는 목적만 남기고 짧게 써요."}]' where drill_id='dr-20260926-ek-m1';
update public.drill_models set best='떠나고 싶은 마음, 클릭 한 번이면 충분해요.', alternatives='["나만의 휴가까지, 클릭 한 번.", "떠날 준비는 끝났어요. 클릭만 남았어요."]' where drill_id='dr-20260926-ek-m2';
update public.drill_models set best='자잘한 버그를 잡고, 더 매끄럽게 다듬었어요.', alternatives='["버그는 잡고, 속도는 올렸어요.", "눈에 띄지 않던 오류까지 고쳐 한층 부드러워졌어요."]' where drill_id='dr-20260926-ek-m3';
update public.drill_models set best='지난주 보내 드린 메일 건으로 다시 연락드립니다.', alternatives='["지난주 메일 건으로 한 번 더 여쭙니다.", "지난주 드린 메일, 확인 부탁드리고자 다시 연락드려요."]' where drill_id='dr-ek-b3';
update public.drill_models set best='부득이한 사정으로 출시가 다음 달로 연기되었습니다.', alternatives='["예상치 못한 사정으로 출시 일정이 다음 달로 미뤄졌습니다.", "불가피한 사정으로 출시를 다음 달로 연기하게 되었습니다."]' where drill_id='dr-ek-b4';
update public.drill_models set best='초안 보시고 의견 주시면 감사하겠습니다.', alternatives='["초안을 어떻게 보셨는지 궁금합니다.", "초안에 의견 남겨 주시면 반영하겠습니다."]', notes='[{"phrase": "I''d love to hear your thoughts", "why": "''듣고 싶습니다''로 직역하기보다 ''의견 주시면 감사하겠습니다''가 업무 메일에서 자연스러워요. I''d love to는 사랑하다가 아니라 공손하게 바라는 말이에요."}, {"phrase": "on the draft", "why": "''초안에 대한 의견''은 번역투예요. ''초안 보시고 의견'', ''초안에 의견''으로 써요."}]' where drill_id='dr-20260926-ek-b3';
update public.drill_models set best='꼭 가 봐. 후회 안 할걸.', alternatives='["무조건 가 봐. 진짜 볼 만해.", "한번 가 봐, 가 볼 만해."]' where drill_id='dr-ek-d3';
update public.terms set examples = replace(examples::text, '그 캠페인은 새로운 세대의 러너들에게 영감을 주었다.', '그 캠페인은 새로운 세대를 달리게 만들었다.')::jsonb where id='t-inspire';
update public.daily_sentences set translation = '그 캠페인은 새로운 세대를 달리게 만들었다.' where translation = '그 캠페인은 새로운 세대의 러너들에게 영감을 주었다.';
commit;
